import assert from 'node:assert/strict';
import {TerminalSessionLedger} from './src/terminal/session-state.mjs';
import {TerminalOutputCredits} from './src/terminal/credits.mjs';
import {readFile} from 'node:fs/promises';import {createHash} from 'node:crypto';
const paths=['src/terminal/session-state.mjs','src/terminal/credits.mjs','tests/terminal-session-state.test.mjs','tests/terminal-credits.test.mjs','src/terminal/contracts.mjs'];
const identity=async()=>Object.fromEntries(await Promise.all(paths.map(async p=>[p,createHash('sha256').update(await readFile(p)).digest('hex')]))),before=await identity();
const results=[],tick=()=>new Promise(r=>setImmediate(r));
const context=(windowId='view',epoch=5,projectId='project')=>({projectId,windowId,epoch});
const spec={sessionId:'session',projectId:'project',profileId:'powershell',cwdDisplay:'D:/Lucru Știință 漢字'};
const request=(lease,inputSequence,data='',overrides={})=>({operationId:'op_'+inputSequence,epoch:5,sessionId:'session',leaseId:lease.leaseId,generation:lease.generation,inputSequence,data,...overrides});
async function check(name,fn){try{const details=await fn();results.push({name,ok:true,details});}catch(e){results.push({name,ok:false,error:e.stack});}}
await check('Empty-input metadata stays finite across all eight sessions and Lock frees every queued item',async()=>{
 const releases=[],writes=[];const ledger=new TerminalSessionLedger({writeInput:p=>{writes.push(p);return new Promise(r=>releases.push(r));}});ledger.resumeInput();const all=[];
 for(let s=0;s<8;s++){const sessionId='s'+s;assert.equal(ledger.register({...spec,sessionId}).ok,true);const lease=ledger.attach(context(),sessionId).value;for(let n=0;n<256;n++)all.push(ledger.input(context(),request(lease,n,'',{sessionId})));assert.equal((await ledger.input(context(),request(lease,256,'',{sessionId}))).code,'CAPACITY_EXCEEDED');assert.equal(ledger.stats(sessionId).pendingInputs,256);assert.equal(ledger.stats(sessionId).queuedInputUtf8Bytes,0);}
 assert.equal(writes.length,8);assert.equal(ledger.register({...spec,sessionId:'ninth'}).code,'CAPACITY_EXCEEDED');ledger.closeInput('lock');for(const release of releases)release({accepted:true});const replies=await Promise.all(all);await tick();assert.equal(replies.length,2048);assert.ok(replies.every(r=>r.code==='LEASE_STALE'));for(let s=0;s<8;s++)assert.equal(ledger.stats('s'+s).pendingInputs,0);assert.equal(ledger.nativeExecutionAdmitted,false);return{pendingMetadataCap:2048,writes:8};
});
await check('Whole Unicode paste refusal does not consume the next sequence and duplicate pending receipt never writes twice',async()=>{
 const releases=[],writes=[],ledger=new TerminalSessionLedger({writeInput:p=>{writes.push(p);return new Promise(r=>releases.push(r));}});ledger.register(spec);ledger.resumeInput();const lease=ledger.attach(context(),'session').value,text='😀'.repeat(8192),all=[];
 for(let i=0;i<8;i++)all.push(ledger.input(context(),request(lease,i,text)));const dup=ledger.input(context(),request(lease,0,text,{operationId:'retry_0'}));assert.equal(ledger.stats('session').queuedInputUtf8Bytes,262144);assert.equal((await ledger.input(context(),request(lease,8,'x'))).code,'CAPACITY_EXCEEDED');
 for(let i=0;i<8;i++){assert.equal(releases.length,i+1);releases[i]({accepted:true});await tick();}assert.ok((await Promise.all(all)).every(r=>r.ok));assert.equal((await dup).operationId,'op_0');const next=ledger.input(context(),request(lease,8,'z'));assert.equal(writes.length,9);releases[8]({accepted:true});assert.equal((await next).ok,true);return{acceptedBytes:262144,retryWrites:0,nextSequenceReusable:true};
});
await check('Fresh epoch/window attachment waits behind old in-flight input but never sends revoked queued or late input',async()=>{
 const releases=[],writes=[],ledger=new TerminalSessionLedger({writeInput:p=>{writes.push(p);return new Promise(r=>releases.push(r));}});ledger.register(spec);ledger.resumeInput();const old=ledger.attach(context(),'session').value,a=ledger.input(context(),request(old,0,'old delivered')),queued=ledger.input(context(),request(old,1,'old queued'));ledger.closeInput('lock');assert.equal((await queued).code,'LEASE_STALE');assert.equal((await ledger.input(context(),request(old,2))).code,'PIN_REQUIRED');ledger.resumeInput();const freshContext=context('fresh',6),fresh=ledger.attach(freshContext,'session').value,next=ledger.input(freshContext,request(fresh,0,'fresh',{epoch:6}));assert.equal(writes.length,1);assert.equal((await ledger.input(context(),request(old,2))).code,'EPOCH_STALE');releases[0]({accepted:true});assert.equal((await a).code,'EPOCH_STALE');await tick();assert.equal(writes.length,2);assert.deepEqual(writes.map(p=>p.data),['old delivered','fresh']);releases[1]({accepted:true});assert.equal((await next).ok,true);return{writes:writes.map(p=>p.data),oldInputNeverReplayed:true};
});
await check('Ambiguous old-generation rejection poisons the session instead of replaying the new queued command',async()=>{
 let reject;const writes=[],ledger=new TerminalSessionLedger({writeInput:p=>{writes.push(p);return new Promise((_,r)=>reject=r);}});ledger.register(spec);ledger.resumeInput();const a=ledger.attach(context(),'session').value,old=ledger.input(context(),request(a,0,'uncertain'));ledger.closeInput('lock');ledger.resumeInput();const b=ledger.attach(context('new'),'session').value,next=ledger.input(context('new'),request(b,0,'must never replay'));reject(Error('ACK lost'));assert.equal((await old).code,'HOST_UNAVAILABLE');assert.equal((await next).code,'LEASE_STALE');await tick();assert.equal(ledger.stats('session').inputUnverified,true);assert.equal(ledger.stats('session').pendingInputs,0);assert.equal(ledger.attach(context(),'session').code,'HOST_UNAVAILABLE');assert.equal(writes.length,1);return{inputUnverified:true,writes:1};
});
await check('1024 empty settled inputs retain only256 receipts; expiry/conflict/gap cannot replay',async()=>{
 let writes=0;const ledger=new TerminalSessionLedger({writeInput:async()=>{writes++;return{accepted:true};}});ledger.register(spec);ledger.resumeInput();const l=ledger.attach(context(),'session').value;for(let n=0;n<1024;n++)assert.equal((await ledger.input(context(),request(l,n))).ok,true);assert.equal(ledger.stats('session').retainedInputReceipts,256);for(const n of [0,1,767])assert.equal((await ledger.input(context(),request(l,n))).code,'INPUT_RECEIPT_EXPIRED');assert.equal((await ledger.input(context(),request(l,768))).ok,true);assert.equal((await ledger.input(context(),request(l,1023,'different'))).code,'REQUEST_REFUSED');assert.equal((await ledger.input(context(),request(l,1025))).code,'REQUEST_REFUSED');assert.equal(writes,1024);return{writes,retained:256};
});
await check('Global output credit exact2MiB, per-lease ACK boundaries and detach refund remain isolated',async()=>{
 const credits=new TerminalOutputCredits();for(let n=0;n<8;n++){assert.equal(credits.attach('lease_'+n,100).ok,true);for(let f=0;f<8;f++)assert.equal(credits.reserve('lease_'+n,{sequence:100+f*32768,utf8Bytes:32768}).ok,true);}assert.equal(credits.stats().outstandingUtf8Bytes,2097152);const before=credits.stats();assert.equal(credits.ack('lease_0',100+32767).code,'REQUEST_REFUSED');assert.deepEqual(credits.stats(),before);assert.equal(credits.ack('lease_0',100+65536).value.releasedUtf8Bytes,65536);assert.equal(credits.ack('lease_0',100+65536).value.releasedUtf8Bytes,0);assert.equal(credits.detach('lease_1').value.releasedUtf8Bytes,262144);assert.equal(credits.ack('lease_1',262244).code,'LEASE_STALE');assert.equal(credits.stats().outstandingUtf8Bytes,1769472);return{remaining:1769472};
});
await check('Independent interval oracle survives20000 deterministic credit/ACK/detach/gap operations',async()=>{
 const credits=new TerminalOutputCredits(),model=new Map();let seed=0x51ae9,unique=0;const rand=n=>{seed=(Math.imul(seed,1664525)+1013904223)>>>0;return seed%n;};let accepted=0,refused=0;
 for(let step=0;step<20000;step++){const keys=[...model.keys()],choice=rand(5);
  if(choice===0||!keys.length){const id='lease_'+unique++,from=rand(10000),actual=credits.attach(id,from),ok=model.size<8;assert.equal(actual.ok,ok);if(ok){model.set(id,{from,end:from,acked:from,frames:[]});accepted++;}else refused++;}
  else{const id=keys[rand(keys.length)],m=model.get(id);
   if(choice===1){const bytes=1+rand(32768),wrong=rand(5)===0,start=m.end+(wrong?1:0),total=[...model.values()].flatMap(x=>x.frames).reduce((n,f)=>n+f.bytes,0),own=m.frames.reduce((n,f)=>n+f.bytes,0),ok=!wrong&&m.frames.length<256&&own+bytes<=262144&&total+bytes<=2097152;const actual=credits.reserve(id,{sequence:start,utf8Bytes:bytes});assert.equal(actual.ok,ok);if(ok){m.end+=bytes;m.frames.push({end:m.end,bytes});accepted++;}else refused++;}
   else if(choice===2){const valid=rand(3)!==0,index=m.frames.length?rand(m.frames.length):-1,through=valid?(index>=0?m.frames[index].end:m.acked):m.end+1,actual=credits.ack(id,through);assert.equal(actual.ok,valid);if(valid){const removed=m.frames.filter(f=>f.end<=through),refund=removed.reduce((n,f)=>n+f.bytes,0);assert.equal(actual.value.releasedUtf8Bytes,refund);m.frames=m.frames.filter(f=>f.end>through);m.acked=through;accepted++;}else refused++;}
   else if(choice===3){const expected=m.frames.reduce((n,f)=>n+f.bytes,0);assert.equal(credits.detach(id).value.releasedUtf8Bytes,expected);model.delete(id);assert.equal(credits.ack(id,m.end).code,'LEASE_STALE');accepted++;}
   else{const next=m.end+1+rand(1000),actual=credits.advanceToRetained(id,next),ok=m.frames.length===0;assert.equal(actual.ok,ok);if(ok){m.end=m.acked=next;accepted++;}else refused++;}}
  const frames=[...model.values()].flatMap(x=>x.frames);assert.deepEqual(credits.stats(),{attachments:model.size,outstandingUtf8Bytes:frames.reduce((n,f)=>n+f.bytes,0),frames:frames.length});}
 return{operations:20000,accepted,refused};
});
await check('One-byte output metadata bound and safe-integer exhaustion cannot mint credit',async()=>{
 const credits=new TerminalOutputCredits();credits.attach('tiny');for(let n=0;n<256;n++)assert.equal(credits.reserve('tiny',{sequence:n,utf8Bytes:1}).ok,true);assert.equal(credits.reserve('tiny',{sequence:256,utf8Bytes:1}).code,'CAPACITY_EXCEEDED');assert.equal(credits.ack('tiny',256).value.releasedUtf8Bytes,256);assert.equal(credits.advanceToRetained('tiny',Number.MAX_SAFE_INTEGER).ok,true);const before=credits.stats();assert.equal(credits.reserve('tiny',{sequence:Number.MAX_SAFE_INTEGER,utf8Bytes:1}).code,'REQUEST_REFUSED');assert.deepEqual(credits.stats(),before);return{framesCap:256,outstanding:0};
});
const after=await identity();assert.deepEqual(after,before);console.log(JSON.stringify({author:'/root/catalogue_view',status:results.every(x=>x.ok)?'INDEPENDENT_PURE_PROBES_COMPLETE':'ADVERSE',before,after,results,pass:results.filter(x=>x.ok).length,fail:results.filter(x=>!x.ok).length,nativeExecution:false},null,2));if(results.some(x=>!x.ok))process.exitCode=1;

